{
  "items": [
    {
      "title": "WBdigital Database: Historical Economic Statistics for West Berlin and East Germany (1928–1968)",
      "url_or_doi": "https://diw-tabellen.informatik.uni-wuerzburg.de/info",
      "justification": "One of the most directly relevant datasets for studying Berlin's economic development during the 1950s. Developed from the German Institute for Economic Research (DIW Berlin) historical weekly reports, this database provides structured economic time series covering West Berlin and the German Democratic Republic, including East Berlin. Indicators include industrial production, employment, wages, consumption, prices, banking, trade, and public finances. Particularly valuable for comparing capitalist West Berlin with socialist East Berlin during the Cold War."
    },
    {
      "title": "DIW Berlin: Historical Wochenbericht Economic Statistics (1928–1968)",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.621116.en/pages/about_the_diw_wochenbericht.html",
      "justification": "Official DIW Berlin resource providing access to digitized historical economic reports and associated statistical time series. The collection covers the entire 1950s and contains detailed economic indicators for Berlin and East Germany. Useful for investigating postwar reconstruction, industrial recovery, employment trends, investment, and differences between the economic systems operating in the divided city."
    },
    {
      "title": "Monthly Economic Statistics for East Germany and East Berlin (1953)",
      "url_or_doi": "https://www.diw.de/de/diw_01.c.958839.de/publikationen/wochenberichte/1953_43_3/monatliche_zahlenuebersicht_mitteldeutschland.html",
      "justification": "A historical statistical publication from DIW Berlin containing monthly economic figures for East Germany, including East Berlin. The 1953 data provide a contemporary perspective on economic conditions under socialist central planning. Useful for examining industrial development, production trends, and economic conditions during the early years of the German Democratic Republic. This is a historical statistical source rather than a standalone modern machine-readable dataset."
    },
    {
      "title": "Statistical Yearbooks of the German Democratic Republic (1955–1960)",
      "url_or_doi": "https://digi.bib.uni-mannheim.de/sammlungen/statistische-jahrbuecher",
      "justification": "The University of Mannheim's digitized statistical yearbook collection includes the official Statistical Yearbooks of the German Democratic Republic beginning in 1955. These publications contain historical statistics on industrial production, economic planning, employment, wages, agriculture, investment, trade, and population. They are important primary sources for studying East Berlin's economic environment under socialism. Researchers should check individual tables to distinguish East Berlin statistics from figures covering the entire GDR."
    },
    {
      "title": "GESIS Historical Statistics: Industrial Production and Labor Productivity in Germany (1950–2014)",
      "url_or_doi": "https://doi.org/10.4232/1.12317",
      "justification": "A historical dataset compiled by Jürgen Sensch and archived by GESIS. It includes industrial net production indices, gross production indices, and labor productivity indicators beginning in 1950. Its geographical coverage includes West Berlin within historical West German aggregates and East Berlin within East German aggregates. Particularly useful for comparing industrial productivity and economic development under capitalist and socialist systems, although the geographical aggregates are not necessarily Berlin-specific."
    },
    {
      "title": "GESIS Historical Statistics: National Accounts, Industry, Prices, Wages, and Public Finances in Germany (1950–1997)",
      "url_or_doi": "https://doi.org/10.4232/1.12079",
      "justification": "A comprehensive historical economic dataset covering national accounts, industrial activity, wages, prices, public finances, social security, and economic development. It provides valuable context for understanding West Germany's postwar social market economy and the broader economic environment surrounding West Berlin during the 1950s. Important limitation: the dataset's West German geographical coverage explicitly excludes Berlin for 1950–1959, making it a contextual comparison source rather than a direct source of Berlin-specific observations for that decade."
    },
    {
      "title": "GESIS Historical Statistics Database (HISTAT)",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/index",
      "justification": "A research database containing historical economic and social statistics for Germany. It provides access to historical time series on industrial development, employment, production, wages, prices, demographic change, and economic transformation. Researchers can use the database to identify studies covering the 1950s and investigate differences between East and West German economic systems. Berlin-specific availability depends on the individual dataset."
    },
    {
      "title": "GDR Labor Market Report: Long-Term Historical Time Series (1949–1989)",
      "url_or_doi": "https://b2find.eudat.eu/dataset/7e5219e1-7d89-567b-b31a-4b47ba9340ee",
      "justification": "A historical labor market dataset covering East Germany during the socialist period. It includes employment by economic sector from 1949 onward and working-age population statistics beginning in 1950. Data are derived from official GDR statistics, historical statistical yearbooks, and reconstructed statistical series. Useful for studying employment structures, labor allocation, and economic planning in the socialist system that governed East Berlin. Regional coverage should be checked before treating individual series as East Berlin-specific."
    },
    {
      "title": "Statistical Yearbook of Berlin: Historical Statistical Publications",
      "url_or_doi": "https://www.voebb.de/aDISWeb/app/prod00?sp=SAK16308258",
      "justification": "A Berlin public library catalog record providing access to digitized historical statistical yearbook collections. These publications are useful for investigating Berlin's longer-term economic development, including population, housing, industry, municipal finances, and employment. The linked digitized holdings primarily cover earlier historical periods, so this resource is best used for establishing prewar economic baselines rather than obtaining complete 1950s data."
    },
    {
      "title": "The WBdigital Database: A Digital Repository for the Historical DIW-Wochenbericht, 1928–1968",
      "url_or_doi": "https://doi.org/10.1515/jbnst-2024-0055",
      "justification": "A scholarly description of the WBdigital historical economic database, explaining its statistical coverage, structure, and research applications. The underlying database includes dedicated economic time series collections for West Berlin and the GDR, including East Berlin. It documents variables related to industrial production, consumption, employment, wages, prices, banking, and government finances. Particularly useful for identifying appropriate datasets and understanding their methodology before conducting a comparative study of Berlin's two economic systems in the 1950s."
    },
    {
      "title": "GESIS Historical Statistics: Population, Economy, Labor, Production, Consumption, and Prices in West Germany (1950–2010)",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/de/project/details/291DF3124A0BDC5C85010D0D12BF9B05",
      "justification": "A historical data compilation covering major indicators of West German economic development from 1950 onward. It includes information about economic activity, employment, industrial production, working hours, consumption, and prices. Useful for analyzing the economic system and postwar growth patterns of West Germany, providing a comparative framework for research on West Berlin's economic development. Researchers should verify whether individual 1950s series include West Berlin before using them as direct evidence about the city."
    }
  ]
}
